package app.manga.common;
import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import org.springframework.web.server.ResponseStatusException;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("code","VALIDATION_ERROR","message","Periksa kembali data yang dikirim."));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("code","VALIDATION_ERROR","message",e.getMessage()));}@ExceptionHandler(IllegalStateException.class)ResponseEntity<?> conflict(IllegalStateException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("code","CONFLICT","message",e.getMessage()));}@ExceptionHandler(UpstreamException.class)ResponseEntity<?> upstream(UpstreamException e){return ResponseEntity.status(e.status()).body(Map.of("code",e.code(),"message",e.getMessage()));}@ExceptionHandler(ResponseStatusException.class)ResponseEntity<?> status(ResponseStatusException e){var status=e.getStatusCode();String message=status==HttpStatus.UNAUTHORIZED?"Email atau password tidak valid.":(e.getReason()==null?"Permintaan tidak dapat diproses.":e.getReason());return ResponseEntity.status(status).body(Map.of("code",status==HttpStatus.UNAUTHORIZED?"UNAUTHORIZED":status==HttpStatus.NOT_FOUND?"NOT_FOUND":"CONFLICT","message",message));}@ExceptionHandler(Exception.class)ResponseEntity<?> other(Exception e){return ResponseEntity.internalServerError().body(Map.of("code","INTERNAL_ERROR","message","Terjadi kesalahan pada server."));}}
